const links={"en": "<aside id=\"bailu-learning-resources\" aria-label=\"Start here\" style=\"background:#f7f6f0;color:#17333c;padding:32px max(24px,calc((100vw - 1080px)/2));font:16px/1.8 system-ui,sans-serif;border-top:1px solid #d8e0da\"><h2 style=\"font-size:22px;margin:0 0 12px\">Start here</h2><ul style=\"display:flex;flex-wrap:wrap;gap:12px 28px;padding:0;list-style:none\"><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/en/learn/\">Bailu Hub: Chinese Internal Martial Arts Practice App</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/en/learn/first-lesson/\">The Bellows Practice: Feel Your Dantian | Bailu Hub</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/en/learn/getting-started/\">Getting Started with Bailu Hub: Your First Practice</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/en/learn/launch-faq/\">Bailu Hub Launch FAQ: Free Release, Availability &amp; Updates</a></li></ul><p style=\"font-size:14px\">Planned launch: November 13, 2026. Subject to review; selected countries and regions.</p></aside>", "zh-cn": "<aside id=\"bailu-learning-resources\" aria-label=\"入门与首课指南\" style=\"background:#f7f6f0;color:#17333c;padding:32px max(24px,calc((100vw - 1080px)/2));font:16px/1.8 system-ui,sans-serif;border-top:1px solid #d8e0da\"><h2 style=\"font-size:22px;margin:0 0 12px\">入门与首课指南</h2><ul style=\"display:flex;flex-wrap:wrap;gap:12px 28px;padding:0;list-style:none\"><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-cn/learn/\">白研社是什么？内家拳练习 App 与首课指南</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-cn/learn/first-lesson/\">丹田初动·拉风箱：白研社首课练什么？</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-cn/learn/getting-started/\">白研社新手使用指南：从看懂首课到记录体会</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-cn/learn/launch-faq/\">白研社首发问答：上线时间、免费版与获取方式</a></li></ul><p style=\"font-size:14px\">App 与小程序预计2026年11月13日上线，实际时间以审核及正式公告为准。</p></aside>", "zh-tw": "<aside id=\"bailu-learning-resources\" aria-label=\"入門與首課指南\" style=\"background:#f7f6f0;color:#17333c;padding:32px max(24px,calc((100vw - 1080px)/2));font:16px/1.8 system-ui,sans-serif;border-top:1px solid #d8e0da\"><h2 style=\"font-size:22px;margin:0 0 12px\">入門與首課指南</h2><ul style=\"display:flex;flex-wrap:wrap;gap:12px 28px;padding:0;list-style:none\"><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-tw/learn/\">白研社是什麼？內家拳練習 App 與首課指南</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-tw/learn/first-lesson/\">丹田初動·拉風箱：白研社首課練什麼？</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-tw/learn/getting-started/\">白研社新手使用指南：從看懂首課到記錄體會</a></li><li><a style=\"color:#22614c;text-underline-offset:4px\" href=\"/zh-tw/learn/launch-faq/\">白研社首發問答：上線時間、免費版與取得方式</a></li></ul><p style=\"font-size:14px\">App 預計2026年11月13日上線，實際時間以審核及正式公告為準。</p></aside>"};
function sync(){
 if(!/^\/(?:(?:en|zh-cn|zh-tw)\/?)?$/.test(location.pathname))return;
 const language=document.documentElement.lang.toLowerCase();
 const lang=language==='zh-hans'?'zh-cn':language==='zh-hant'?'zh-tw':language;
 const c=metadata[lang];if(!c)return;
 const setLink=(rel,href,hreflang)=>{const el=document.head.querySelector(hreflang?`link[rel="${rel}"][hreflang="${hreflang}"]`:`link[rel="${rel}"]`);if(el&&el.getAttribute('href')!==href)el.setAttribute('href',href);};
 const canonical=c.origin+`/${lang}/`;
 setLink('canonical',canonical);
 for(const [l,m] of Object.entries(metadata))setLink('alternate',m.origin+`/${l}/`,m.hreflang);
 setLink('alternate','https://www.bailuhub.com/en/','x-default');
 const og=document.head.querySelector('meta[property="og:url"]');if(og&&og.content!==canonical)og.content=canonical;

 if(document.title!==c.title)document.title=c.title;
 for(const [attribute,key,value] of [['name','description',c.description],['property','og:title',c.title],['property','og:description',c.description],['property','og:site_name',c.name],['name','twitter:title',c.title],['name','twitter:description',c.description]]){
  const el=document.head.querySelector(`meta[${attribute}="${key}"]`);if(el&&el.content!==value)el.content=value;
 }
 const el=document.getElementById('bailu-learning-resources');if(el&&el.dataset.language!==lang){el.outerHTML=links[lang];document.getElementById('bailu-learning-resources').dataset.language=lang;}
}
const observer=new MutationObserver(sync);
observer.observe(document.head,{subtree:true,childList:true,attributes:true});
observer.observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync,{once:true});else sync();
